17	package org.springframework.samples.petclinic;
18	
19	import static org.assertj.core.api.Assertions.assertThat;
20	import static org.hamcrest.Matchers.containsString;
21	import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
22	import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.content;
23	import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;
24	import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.view;
25	
26	import org.junit.jupiter.api.Test;
27	import org.springframework.beans.factory.annotation.Autowired;
28	import org.springframework.boot.test.context.SpringBootTest;
29	import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;
30	import org.springframework.jdbc.core.JdbcTemplate;
31	import org.springframework.test.web.servlet.MockMvc;
32	import org.springframework.test.web.servlet.ResultActions;
33	
34	/**
35	 * Adds, edits and clears a pet's microchip number through the forms on H2, and reads the
36	 * stored value from the database after each step. The test runs no transaction of its
37	 * own, so each request saves as it does in the running app, with a detached pet
38	 * ({@code spring.jpa.open-in-view=false}).
39	 */
40	@SpringBootTest
41	@AutoConfigureMockMvc
42	class PetMicrochipNumberIntegrationTests {
43	
44		private static final int OWNER_ID = 3;
45	
46		private static final String FORM = "pets/createOrUpdatePetForm";
47	
48		@Autowired
49		private MockMvc mockMvc;
50	
51		@Autowired
52		private JdbcTemplate jdbc;
53	
54		@Test
55		void microchipNumberIsAddedReplacedAndClearedThroughTheForms() throws Exception {
56			this.mockMvc
57				.perform(post("/owners/{ownerId}/pets/new", OWNER_ID).param("name", "Chippy")
58					.param("type", "dog")
59					.param("birthDate", "2020-01-01")
60					.param("microchipNumber", "985141000123456"))
61				.andExpect(status().is3xxRedirection());
62			Integer petId = this.jdbc.queryForObject("SELECT id FROM pets WHERE owner_id = ? AND name = ?", Integer.class,
63					OWNER_ID, "Chippy");
64			assertThat(storedMicrochipNumber(petId)).isEqualTo("985141000123456");
65	
66			edit(petId, "12345").andExpect(status().isOk())
67				.andExpect(view().name(FORM))
68				.andExpect(content().string(containsString("must be 15 digits")));
69			assertThat(storedMicrochipNumber(petId)).isEqualTo("985141000123456");
70	
71			edit(petId, "985141000654321").andExpect(status().is3xxRedirection());
72			assertThat(storedMicrochipNumber(petId)).isEqualTo("985141000654321");
73	
74			edit(petId, "").andExpect(status().is3xxRedirection());
75			assertThat(storedMicrochipNumber(petId)).isNull();
76		}
77	
78		private ResultActions edit(int petId, String microchipNumber) throws Exception {
79			return this.mockMvc.perform(post("/owners/{ownerId}/pets/{petId}/edit", OWNER_ID, petId).param("name", "Chippy")
80				.param("type", "dog")
81				.param("birthDate", "2020-01-01")
82				.param("microchipNumber", microchipNumber));
83		}
84	
85		private String storedMicrochipNumber(int petId) {
86			return this.jdbc.queryForObject("SELECT microchip_number FROM pets WHERE id = ?", String.class, petId);
87		}
88	
89	}
