27	
28	import org.junit.jupiter.api.Test;
29	import org.springframework.beans.factory.annotation.Autowired;
30	import org.springframework.boot.data.jpa.test.autoconfigure.DataJpaTest;
31	import org.springframework.boot.jdbc.test.autoconfigure.AutoConfigureTestDatabase;
32	import org.springframework.boot.jdbc.test.autoconfigure.AutoConfigureTestDatabase.Replace;
33	import org.springframework.data.domain.Page;
34	import org.springframework.data.domain.Pageable;
35	import org.springframework.samples.petclinic.owner.Owner;
36	import org.springframework.samples.petclinic.owner.OwnerRepository;
37	import org.springframework.samples.petclinic.owner.Pet;
38	import org.springframework.samples.petclinic.owner.PetType;
39	import org.springframework.samples.petclinic.owner.PetTypeRepository;
40	import org.springframework.samples.petclinic.owner.Visit;
41	import org.springframework.samples.petclinic.vet.Vet;
42	import org.springframework.samples.petclinic.vet.VetRepository;
43	import org.springframework.transaction.annotation.Transactional;
44	
45	/**
46	 * Integration test of the Service and the Repository layer.
47	 * <p>
48	 * ClinicServiceSpringDataJpaTests subclasses benefit from the following services provided
49	 * by the Spring TestContext Framework:
50	 * </p>
51	 * <ul>
52	 * <li><strong>Spring IoC container caching</strong> which spares us unnecessary set up
53	 * time between test execution.</li>
54	 * <li><strong>Dependency Injection</strong> of test fixture instances, meaning that we
55	 * don't need to perform application context lookups. See the use of
56	 * {@link Autowired @Autowired} on the <code> </code> instance variable, which uses
57	 * autowiring <em>by type</em>.
58	 * <li><strong>Transaction management</strong>, meaning each test method is executed in
59	 * its own transaction, which is automatically rolled back by default. Thus, even if tests
60	 * insert or otherwise change database state, there is no need for a teardown or cleanup
61	 * script.
62	 * <li>An {@link org.springframework.context.ApplicationContext ApplicationContext} is
63	 * also inherited and can be used for explicit bean lookup if necessary.</li>
64	 * </ul>
65	 *
66	 * @author Ken Krebs
67	 * @author Rod Johnson
68	 * @author Juergen Hoeller
69	 * @author Sam Brannen
70	 * @author Michael Isvy
71	 * @author Dave Syer
72	 */
73	@DataJpaTest
74	// Ensure that if the mysql profile is active we connect to the real database:
75	@AutoConfigureTestDatabase(replace = Replace.NONE)
76	// @TestPropertySource("/application-postgres.properties")
77	class ClinicServiceTests {
78	
79		@Autowired
80		protected OwnerRepository owners;
81	
82		@Autowired
83		protected PetTypeRepository types;
84	
85		@Autowired
86		protected VetRepository vets;
87	
88		private final Pageable pageable = Pageable.unpaged();
89	
90		@Test
91		void shouldFindOwnersByLastName() {
92			Page<Owner> owners = this.owners.findByLastNameStartingWith("Davis", pageable);
93			assertThat(owners).hasSize(2);
94	
95			owners = this.owners.findByLastNameStartingWith("Daviss", pageable);
96			assertThat(owners).isEmpty();
97		}
98	
99		@Test
100		void shouldFindSingleOwnerWithPet() {
101			Optional<Owner> optionalOwner = this.owners.findById(1);
102			assertThat(optionalOwner).isPresent();
103			Owner owner = optionalOwner.get();
104			assertThat(owner.getLastName()).startsWith("Franklin");
105			assertThat(owner.getPets()).hasSize(1);
106			assertThat(owner.getPets().get(0).getType()).isNotNull();
107			assertThat(owner.getPets().get(0).getType().getName()).isEqualTo("cat");
108		}
109	
110		@Test
111		@Transactional
112		void shouldInsertOwner() {
113			Page<Owner> owners = this.owners.findByLastNameStartingWith("Schultz", pageable);
114			int found = (int) owners.getTotalElements();
115	
116			Owner owner = new Owner();
117			owner.setFirstName("Sam");
118			owner.setLastName("Schultz");
119			owner.setAddress("4, Evans Street");
120			owner.setCity("Wollongong");
121			owner.setTelephone("4444444444");
122			this.owners.save(owner);
123			assertThat(owner.getId()).isNotZero();
124	
125			owners = this.owners.findByLastNameStartingWith("Schultz", pageable);
126			assertThat(owners.getTotalElements()).isEqualTo(found + 1);
127		}
128	
129		@Test
130		@Transactional
131		void shouldUpdateOwner() {
132			Optional<Owner> optionalOwner = this.owners.findById(1);
133			assertThat(optionalOwner).isPresent();
134			Owner owner = optionalOwner.get();
135			String oldLastName = owner.getLastName();
136			String newLastName = oldLastName + "X";
137	
138			owner.setLastName(newLastName);
139			this.owners.save(owner);
140	
141			// retrieving new name from database
142			optionalOwner = this.owners.findById(1);
143			assertThat(optionalOwner).isPresent();
144			owner = optionalOwner.get();
145			assertThat(owner.getLastName()).isEqualTo(newLastName);
146		}
147	
148		@Test
149		void shouldFindAllPetTypes() {
150			Collection<PetType> petTypes = this.types.findPetTypes();
151	
152			PetType petType1 = EntityUtils.getById(petTypes, PetType.class, 1);
153			assertThat(petType1.getName()).isEqualTo("cat");
154			PetType petType4 = EntityUtils.getById(petTypes, PetType.class, 4);
155			assertThat(petType4.getName()).isEqualTo("snake");
156		}
157	
158		@Test
159		@Transactional
160		void shouldInsertPetIntoDatabaseAndGenerateId() {
161			Optional<Owner> optionalOwner = this.owners.findById(6);
162			assertThat(optionalOwner).isPresent();
163			Owner owner6 = optionalOwner.get();
164	
165			int found = owner6.getPets().size();
166	
167			Pet pet = new Pet();
168			pet.setName("bowser");
169			Collection<PetType> types = this.types.findPetTypes();
170			pet.setType(EntityUtils.getById(types, PetType.class, 2));
171			pet.setBirthDate(LocalDate.now());
172			owner6.addPet(pet);
173			assertThat(owner6.getPets()).hasSize(found + 1);
174	
175			this.owners.save(owner6);
176	
177			optionalOwner = this.owners.findById(6);
178			assertThat(optionalOwner).isPresent();
179			owner6 = optionalOwner.get();
180			assertThat(owner6.getPets()).hasSize(found + 1);
181			// checks that id has been generated
182			pet = owner6.getPet("bowser");
183			assertThat(pet.getId()).isNotNull();
184		}
185	
186		@Test
187		@Transactional
188		void shouldUpdatePetName() {
189			Optional<Owner> optionalOwner = this.owners.findById(6);
190			assertThat(optionalOwner).isPresent();
191			Owner owner6 = optionalOwner.get();
192	
193			Pet pet7 = owner6.getPet(7);
194			String oldName = pet7.getName();
195	
196			String newName = oldName + "X";
197			pet7.setName(newName);
198			this.owners.save(owner6);
199	
200			optionalOwner = this.owners.findById(6);
201			assertThat(optionalOwner).isPresent();
202			owner6 = optionalOwner.get();
203			pet7 = owner6.getPet(7);
204			assertThat(pet7.getName()).isEqualTo(newName);
205		}
206	
207		@Test
208		void shouldFindVets() {
209			Collection<Vet> vets = this.vets.findAll();
210	
211			Vet vet = EntityUtils.getById(vets, Vet.class, 3);
212			assertThat(vet.getLastName()).isEqualTo("Douglas");
213			assertThat(vet.getNrOfSpecialties()).isEqualTo(2);
214			assertThat(vet.getSpecialties().get(0).getName()).isEqualTo("dentistry");
215			assertThat(vet.getSpecialties().get(1).getName()).isEqualTo("surgery");
216		}
217	
218		@Test
219		@Transactional
220		void shouldAddNewVisitForPet() {
221			Optional<Owner> optionalOwner = this.owners.findById(6);
222			assertThat(optionalOwner).isPresent();
223			Owner owner6 = optionalOwner.get();
224	
225			Pet pet7 = owner6.getPet(7);
226			int found = pet7.getVisits().size();
227			Visit visit = new Visit();
228			visit.setDescription("test");
229	
230			owner6.addVisit(pet7.getId(), visit);
231			this.owners.save(owner6);
232	
233			assertThat(pet7.getVisits()) //
234				.hasSize(found + 1) //
235				.allMatch(value -> value.getId() != null);
236		}
237	
238		@Test
239		void shouldFindVisitsByPetId() {
240			Optional<Owner> optionalOwner = this.owners.findById(6);
241			assertThat(optionalOwner).isPresent();
242			Owner owner6 = optionalOwner.get();
243	
244			Pet pet7 = owner6.getPet(7);
245			Collection<Visit> visits = pet7.getVisits();
246	
247			assertThat(visits) //
248				.hasSize(2) //
249				.element(0)
250				.extracting(Visit::getDate)
251				.isNotNull();
252		}
253	
254		@Test
255		@Transactional
256		void shouldFailToInsertDuplicatePetNameForSameOwner() {
257			Optional<Owner> optionalOwner = this.owners.findById(1);
258			assertThat(optionalOwner).isPresent();
259			Owner owner = optionalOwner.get();
260	
261			Pet pet1 = new Pet();
262			pet1.setName("DuplicatePetName");
263			Collection<PetType> types = this.types.findPetTypes();
264			pet1.setType(EntityUtils.getById(types, PetType.class, 1));
265			pet1.setBirthDate(LocalDate.now());
266			owner.addPet(pet1);
267			this.owners.saveAndFlush(owner);
268	
269			Pet pet2 = new Pet();
270			pet2.setName("duplicatepetname"); // Case-insensitive duplicate name
271			pet2.setType(EntityUtils.getById(types, PetType.class, 1));
272			pet2.setBirthDate(LocalDate.now());
273			owner.addPet(pet2);
274	
275			assertThrows(DataIntegrityViolationException.class, () -> {
276				this.owners.saveAndFlush(owner);
277			});
278		}
279	
280		@Test
281		@Transactional
282		void shouldAllowSamePetNameForDifferentOwners() {
283			Collection<PetType> types = this.types.findPetTypes();
284			PetType catType = EntityUtils.getById(types, PetType.class, 1);
285	
286			Optional<Owner> owner1Opt = this.owners.findById(1);
287			assertThat(owner1Opt).isPresent();
288			Owner owner1 = owner1Opt.get();
289	
290			Pet pet1 = new Pet();
291			pet1.setName("SamePetName");
292			pet1.setType(catType);
293			pet1.setBirthDate(LocalDate.now());
294			owner1.addPet(pet1);
295			this.owners.saveAndFlush(owner1);
296	
297			Optional<Owner> owner2Opt = this.owners.findById(2);
298			assertThat(owner2Opt).isPresent();
299			Owner owner2 = owner2Opt.get();
300	
301			Pet pet2 = new Pet();
302			pet2.setName("samepetname"); // Case-insensitive duplicate name, but for a
303											// different owner
304			pet2.setType(catType);
305			pet2.setBirthDate(LocalDate.now());
306			owner2.addPet(pet2);
307	
308			// Saving for different owner should succeed
309			this.owners.saveAndFlush(owner2);
310	
311			// Verify both exist
312			assertThat(owner1.getPet("SamePetName")).isNotNull();
313			assertThat(owner2.getPet("samepetname")).isNotNull();
314		}
315	
316		@Test
317		@Transactional
318		void shouldFindMicrochipNumberOfAnotherPetButNotOfThePetItself() {
319			Collection<PetType> types = this.types.findPetTypes();
320			Owner owner1 = this.owners.findById(1).orElseThrow();
321	
322			Pet chipped = new Pet();
323			chipped.setName("Chipped");
324			chipped.setType(EntityUtils.getById(types, PetType.class, 1));
325			chipped.setBirthDate(LocalDate.now());
326			chipped.setMicrochipNumber("985141000123456");
327			owner1.addPet(chipped);
328			this.owners.saveAndFlush(owner1);
329	
330			Integer chippedId = this.owners.findById(1).orElseThrow().getPet("Chipped").getId();
331			Integer otherPetId = this.owners.findById(2).orElseThrow().getPets().get(0).getId();
332			assertThat(chippedId).isNotNull();
333			assertThat(otherPetId).isNotEqualTo(chippedId);
334	
335			assertThat(this.owners.existsPetWithMicrochipNumber("985141000123456")).isTrue();
336			assertThat(this.owners.existsAnotherPetWithMicrochipNumber("985141000123456", otherPetId)).isTrue();
337			assertThat(this.owners.existsAnotherPetWithMicrochipNumber("985141000123456", chippedId)).isFalse();
338			assertThat(this.owners.existsPetWithMicrochipNumber("985141000654321")).isFalse();
339		}
340	
341		@Test
342		@Transactional
343		void shouldTestMicrochipNumberAndIdOnTheSamePet() {
344			PetType catType = EntityUtils.getById(this.types.findPetTypes(), PetType.class, 1);
345	
346			Owner owner = new Owner();
347			owner.setFirstName("Sam");
348			owner.setLastName("Schultz");
349			owner.setAddress("4, Evans Street");
350			owner.setCity("Wollongong");
351			owner.setTelephone("4444444444");
352			Pet a = new Pet();
353			a.setName("ChippedA");
354			a.setType(catType);
355			a.setBirthDate(LocalDate.now());
356			a.setMicrochipNumber("985141000123456");
357			owner.addPet(a);
358			Pet b = new Pet();
359			b.setName("UnchippedB");
360			b.setType(catType);
361			b.setBirthDate(LocalDate.now());
362			owner.addPet(b);
363			this.owners.saveAndFlush(owner);
364	
365			Owner saved = this.owners.findById(owner.getId()).orElseThrow();
366			Integer aId = saved.getPet("ChippedA").getId();
367			Integer bId = saved.getPet("UnchippedB").getId();
368			assertThat(saved.getPets()).hasSize(2);
369	
370			// A query that tested the number on A and the id on B (both of the same owner)
371			// would find A's own number for A.
372			assertThat(this.owners.existsAnotherPetWithMicrochipNumber("985141000123456", aId)).isFalse();
373			assertThat(this.owners.existsAnotherPetWithMicrochipNumber("985141000123456", bId)).isTrue();
374		}
375	
376		@Test
377		@Transactional
378		void shouldSaveTwoPetsWithoutMicrochipNumber() {
379			Collection<PetType> types = this.types.findPetTypes();
380			PetType catType = EntityUtils.getById(types, PetType.class, 1);
381	
382			Owner owner1 = this.owners.findById(1).orElseThrow();
383			Pet first = new Pet();
384			first.setName("NoChipOne");
385			first.setType(catType);
386			first.setBirthDate(LocalDate.now());
387			owner1.addPet(first);
388			this.owners.saveAndFlush(owner1);
389	
390			Owner owner2 = this.owners.findById(2).orElseThrow();
391			Pet second = new Pet();
392			second.setName("NoChipTwo");
393			second.setType(catType);
394			second.setBirthDate(LocalDate.now());
395			owner2.addPet(second);
396			this.owners.saveAndFlush(owner2);
397	
398			Pet savedFirst = this.owners.findById(1).orElseThrow().getPet("NoChipOne");
399			Pet savedSecond = this.owners.findById(2).orElseThrow().getPet("NoChipTwo");
400			assertThat(savedFirst.getId()).isNotNull();
401			assertThat(savedFirst.getMicrochipNumber()).isNull();
402			assertThat(savedSecond.getId()).isNotNull();
